#!/usr/bin/env bash
# Generated by gemma4-bench for run 20261014-2031-sgl-b-tau2cfg-p64-h200-1x01-ci-sbhigh; the measurement lives in recipes/run_cell.sh.
set -o pipefail
source "$(dirname "$0")/../../benchmark_lib.sh"
check_env_vars CONC PORT INFMAX_CONTAINER_WORKSPACE RESULT_FILENAME
export BENCH_DIR="$INFMAX_CONTAINER_WORKSPACE/bench-20261014-2031-sgl-b-tau2cfg-p64-h200-1x01-ci-sbhigh"
rm -rf "$BENCH_DIR"; mkdir -p "$BENCH_DIR/datasets"
cp -r "$INFMAX_CONTAINER_WORKSPACE/benchmarks/gemma4j/20261014-2031-sgl-b-tau2cfg-p64-h200-1x01-ci-sbhigh/." "$BENCH_DIR/"
export SPEEDBENCH_CONFIG=throughput_8k
resolve_speedbench_dataset || exit 1
cp "$SPEEDBENCH_FILE" "$BENCH_DIR/datasets/throughput_8k.jsonl"
_want=$(sed -n 's/^SPEEDBENCH_SHA=//p' "$BENCH_DIR/run.env"); _got=$(sha256sum "$BENCH_DIR/datasets/throughput_8k.jsonl" | cut -d' ' -f1)
[ "$_want" = "$_got" ] || { echo "dataset sha256 $_got != recorded SPEEDBENCH_SHA $_want" >&2; exit 1; }
sed -i "s|/bench/|$BENCH_DIR/|g" "$BENCH_DIR/run.env" "$BENCH_DIR"/launches/*/launch.env
sed -i 's|^EXECUTOR=.*|EXECUTOR=ci|; s|^PORT=.*|PORT='"$PORT"'|' "$BENCH_DIR/run.env"
for f in "$BENCH_DIR"/launches/*/launch.env; do
  if grep -q '^WORKLOAD=speedbench$' "$f"; then sed -i 's|^POINTS=.*|POINTS="$CONC:0"|' "$f"; else rm -rf "$(dirname "$f")"; fi
done
bash "$BENCH_DIR/recipes/run_cell.sh"; rc=$?
# one server per CI job: keep this job's log next to its point, so another job's log never stands in for it
for p in "$BENCH_DIR"/points/*/; do
  k=$(basename "$p"); l="${k%-c*}"
  cp "$BENCH_DIR/launches/$l/server.log" "$p/server.log" 2>/dev/null || true
done
OUT="${RESULT_DIR:-$INFMAX_CONTAINER_WORKSPACE/results}/speedbench_aiperf/bench"
mkdir -p "$OUT" && cp -r "$BENCH_DIR/points" "$BENCH_DIR/launches" "$BENCH_DIR/status.json" "$OUT/"
raw=$(ls "$BENCH_DIR"/points/*/raw/result.json 2>/dev/null | head -1)
[ -n "$raw" ] && cp "$raw" "$INFMAX_CONTAINER_WORKSPACE/$RESULT_FILENAME.json"
exit $rc
